catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

	if (newValue == "Yes") {
		g_form.setDisplay('auto_renew_days_before_expiry', true);
        g_form.setValue('auto_renew_days_before_expiry', 30);
		g_form.setValue('renewal_tracking', 'none');
		g_form.setDisabled('renewal_tracking', true);
	} else {
		g_form.setDisplay('auto_renew_days_before_expiry', false);
        g_form.setValue('auto_renew_days_before_expiry', '');
		g_form.setDisabled('renewal_tracking', false);
	}

   //Type appropriate comment here, and begin script below

}
